            {hasPostIntubationHypotensionResponse && (
              <PostIntubationHypotensionTray
                assessment={props.resuscitation.postIntubationHypotensionAssessment}
                onAction={props.onPostIntubationHypotensionResponse ?? (() => {})} />
            )}
