function PostInfarctionShockTray({ assessment, scenarioVersion, guidance = 'unassisted', demonstrating = false, onAction }: {
  assessment?: NonNullable<ActionCockpitProps['resuscitation']['postInfarctionShockAssessment']>;
  scenarioVersion: string;
  guidance?: GuidanceLevel;
  demonstrating?: boolean;
  onAction: NonNullable<ActionCockpitProps['onPostInfarctionShockResponse']>;
}) {
  const trajectory = assessment?.trajectoryAtTick != null;
  const causes = assessment?.causesAtTick != null;
  const transfer = assessment?.transferAtTick != null;
  const bridge = assessment?.bridgeAtTick != null;
  const handoff = assessment?.handoffAtTick != null;
  const prompt = demonstrating ? null
    : postInfarctionShockInlinePrompt(guidance, { scenarioVersion, patient: assessment });
  const act = demonstrating ? undefined : onAction;
  return (
    <div style={{ display: 'grid', gap: 'var(--space-4)' }}>
    {demonstrating && <p className="field__hint" role="status">Watching the worked example. The controls stay visible and do not respond.</p>}
    {prompt && <aside className="syringe" aria-label="Private tutor">
      <div className="syringe__name">A moment to think</div>
      <p className="syringe__remaining">{prompt.suggestion}</p>
      <p className="syringe__remaining">{prompt.because}</p>
    </aside>}
    <div className="tray-grid">
      <section className="syringe" aria-labelledby="post-infarction-shock-trajectory-title">
        <div id="post-infarction-shock-trajectory-title" className="syringe__name">Pressure moved. Perfusion did not.</div>
        <Badge kind="teaching">brain · skin · kidney · lactate · congestion · pressure</Badge>
        <div className="syringe__meta">MAP 57 → 64 · urine 8 mL/h · lactate 4.2 → 5.1</div>
        <p className="syringe__remaining" role="status">
          {causes && transfer ? 'Causes open · regional shock center contacted'
            : trajectory ? 'Inadequate response · reopen causes and contact help in parallel'
              : 'A better MAP is not shock resolution'}
        </p>
        <div className="syringe__presets">
          <Button className="crisis-drug__action" disabled={trajectory}
            aria-disabled={demonstrating} onClick={act ? () => act('reconcile-post-infarction-shock-trajectory') : undefined}>Reconcile failure to improve</Button>
          <Button className="crisis-drug__action" disabled={!trajectory || causes}
            aria-disabled={demonstrating} onClick={act ? () => act('reopen-post-infarction-shock-causes') : undefined}>Reopen causes + reported care</Button>
          <Button className="crisis-drug__action" disabled={!trajectory || transfer}
            aria-disabled={demonstrating} onClick={act ? () => act('contact-post-infarction-shock-center') : undefined}>Contact local + regional shock teams</Button>
        </div>
        <p className="field__hint">Immediate post-PCI findings are snapshots. Recurrent ischemia, mechanical, RV, rhythm, bleeding, vasodilated, and obstructive causes remain open.</p>
      </section>
      <section className="syringe" aria-labelledby="post-infarction-shock-bridge-title">
        <div id="post-infarction-shock-bridge-title" className="syringe__name">Build the bridge. Keep the exit open.</div>
        <Badge kind="teaching">perfusion · congestion · oxygenation · rhythm · candidacy · transport</Badge>
        <div className="syringe__meta">No blind fluid · no universal target · no routine device</div>
        <p className="syringe__remaining" role="status">
          {handoff ? 'Shock unresolved · owners + triggers handed off'
            : bridge ? 'Bridge recorded · allow reassessment time'
              : causes && transfer ? 'Consultation active · individualized bridge due'
                : 'Cause review + regional consultation pending'}
        </p>
        <div className="syringe__presets">
          <Button className="crisis-drug__action" disabled={!causes || !transfer || bridge}
            aria-disabled={demonstrating} onClick={act ? () => act('record-post-infarction-shock-bridge') : undefined}>Record individualized potential-transport bridge</Button>
          <Button className="crisis-drug__action" disabled={!bridge || handoff}
            aria-disabled={demonstrating} onClick={act ? () => act('handoff-post-infarction-shock-trajectory') : undefined}>Reassess + hand off unresolved work</Button>
        </div>
        <p className="field__hint">Consultation is not transfer authorization. Stability, contraindications, preferences, accepting-center selection, support, transport, disposition, and outcome remain expert work.</p>
      </section>
    </div>
    </div>
  );
}

function AfRvrTray({ assessment, scenarioVersion, guidance = 'unassisted', demonstrating = false, onAction }: {
  assessment?: NonNullable<ActionCockpitProps['resuscitation']['afRvrAssessment']>;
  scenarioVersion: string;
  guidance?: GuidanceLevel;
  demonstrating?: boolean;
  onAction: NonNullable<ActionCockpitProps['onAfRvrResponse']>;
}) {
  const stability = assessment?.stabilityAtTick != null;
  const context = assessment?.contextAtTick != null;
  const rateIntent = assessment?.rateIntentAtTick != null;
  const stroke = assessment?.strokePreventionAtTick != null;
  const reassessed = assessment?.reassessmentAtTick != null;
  const prompt = demonstrating ? null
    : afRvrInlinePrompt(guidance, { scenarioVersion, patient: assessment });
  const act = demonstrating ? undefined : onAction;
  return (
    <div style={{ display: 'grid', gap: 'var(--space-4)' }}>
    {demonstrating && <p className="field__hint" role="status">Watching the worked example. The controls stay visible and do not respond.</p>}
    {prompt && <aside className="syringe" aria-label="Private tutor">
      <div className="syringe__name">A moment to think</div>
      <p className="syringe__remaining">{prompt.suggestion}</p>
      <p className="syringe__remaining">{prompt.because}</p>
    </aside>}
    <div className="tray-grid">
      <section className="syringe" aria-labelledby="af-rvr-stability-title">
        <div id="af-rvr-stability-title" className="syringe__name">Treat the patient before the number.</div>
        <Badge kind="teaching">rhythm · pressure · perfusion · ischemia · heart failure</Badge>
        <div className="syringe__meta">142/min irregular · stable pressure · no shock, ischemia, or acute HF</div>
        <p className="syringe__remaining" role="status">
          {rateIntent ? 'Patient-specific rate intent recorded · no treatment delivered'
            : context ? 'Duration uncertain · LVEF 55% · patient-specific plan due'
              : stability ? 'Stable now · review context before strategy'
                : 'Heart rate alone does not define instability'}
        </p>
        <div className="syringe__presets">
          <Button className="crisis-drug__action" disabled={stability}
            aria-disabled={demonstrating} onClick={act ? () => act('reconcile-af-rvr-rhythm-and-stability') : undefined}>Reconcile rhythm + stability</Button>
          <Button className="crisis-drug__action" disabled={!stability || context}
            aria-disabled={demonstrating} onClick={act ? () => act('review-af-rvr-context-and-triggers') : undefined}>Review duration + contributors</Button>
          <Button className="crisis-drug__action" disabled={!context || rateIntent}
            aria-disabled={demonstrating} onClick={act ? () => act('record-af-rvr-rate-control-intent') : undefined}>Record patient-specific rate intent</Button>
        </div>
        <p className="field__hint">Instability changes urgency. In a stable patient, ventricular function, pressure, symptoms, contraindications, and interactions shape acute rate-control selection.</p>
      </section>
      <section className="syringe" aria-labelledby="af-rvr-stroke-title">
        <div id="af-rvr-stroke-title" className="syringe__name">Rate is one lane. Stroke prevention is another.</div>
        <Badge kind="teaching">validated risk · bleeding · preference · duration · reassessment</Badge>
        <div className="syringe__meta">Duration uncertain · risk not low · cardioversion not assumed</div>
        <p className="syringe__remaining" role="status">
          {reassessed ? '96/min · still AF · symptoms improved · ownership recorded'
            : stroke ? 'Stroke-prevention context recorded · reassess the whole patient'
              : rateIntent ? 'Rate lane recorded · stroke-prevention lane remains'
                : 'Rate-control context pending'}
        </p>
        <div className="syringe__presets">
          <Button className="crisis-drug__action" disabled={!rateIntent || stroke}
            aria-disabled={demonstrating} onClick={act ? () => act('record-af-rvr-stroke-prevention-intent') : undefined}>Review stroke prevention + cardioversion context</Button>
          <Button className="crisis-drug__action" disabled={!stroke || reassessed}
            aria-disabled={demonstrating} onClick={act ? () => act('reassess-af-rvr-trajectory-and-follow-up') : undefined}>Reassess trajectory + ownership</Button>
        </div>
        <p className="field__hint">Better can still be AF. No score, agent, dose, anticoagulation decision, cardioversion, disposition, prognosis, or outcome is supplied.</p>
      </section>
    </div>
    </div>
  );
}

